func testAccDNSOutboundEndpoint_dnsOutboundEndpointBasicExample(context map[string]interface{}) string {
	return acctest.Nprintf(`
resource "google_compute_network" "network" {
  name                    = "%{network_name}"
  auto_create_subnetworks = false
}

resource "google_compute_subnetwork" "subnetwork" {
  name          = "%{subnetwork_name}"
  network       = google_compute_network.network.id
  ip_cidr_range = "10.0.0.0/24"
  region        = "us-central1"
}

resource "google_compute_subnetwork" "proxy_subnetwork" {
  name          = "%{proxy_subnetwork_name}"
  network       = google_compute_network.network.id
  ip_cidr_range = "10.0.1.0/24"
  region        = "us-central1"
  purpose       = "REGIONAL_MANAGED_PROXY"
  role          = "ACTIVE"
}

resource "google_dns_outbound_endpoint" "example-endpoint" {
  name        = "%{outbound_endpoint_name}"
  location    = "us-central1"
  network     = google_compute_network.network.id
  subnetwork  = google_compute_subnetwork.subnetwork.id
  endpoint_ip = "10.0.0.10"

  depends_on = [
    google_compute_subnetwork.proxy_subnetwork
  ]
}
`, context)
}

